    pub(crate) fn local_symbol_key(shape: u16, ordinal: u32) -> Option<FieldKey> {
        match shape {
            27 => Some(FieldKey::new(27, ordinal, 32769)),
            31 => Some(FieldKey::new(31, ordinal, 32769)),
            33 => Some(FieldKey::new(33, ordinal, 32769)),
            34 => Some(FieldKey::new(34, ordinal, 32769)),
            35 => Some(FieldKey::new(35, ordinal, 32769)),
            37 => Some(FieldKey::new(37, ordinal, 32769)),
            38 => Some(FieldKey::new(38, ordinal, 32769)),
            40 => Some(FieldKey::new(40, ordinal, 32769)),
            46 => Some(FieldKey::new(46, ordinal, 32769)),
            52 => Some(FieldKey::new(52, ordinal, 32769)),
            178 => Some(FieldKey::new(178, ordinal, 32769)),
            179 => Some(FieldKey::new(179, ordinal, 32769)),
            182 => Some(FieldKey::new(182, ordinal, 32769)),
            183 => Some(FieldKey::new(183, ordinal, 32769)),
            _ => None,
        }
    }

